package org.jlinalg.cli;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.workflow.NfcoreInputBindings;
import static org.jlinalg.cli.NextflowFiles.*;

/** Full cohort materialization and source-only path bindings; no source/scientific substitutions. */
final class NfcoreHic210Prepare {
    private NfcoreHic210Prepare(){ }
    static final String EXTERNAL="// No institutional overrides selected; explicit local FASTA and complete cohort.\n";
    record Read(String sample,int library,String first,String second,String firstRelative,String secondRelative){ }
    static String basename(String p){return p.substring(p.lastIndexOf('/')+1);}
    static List<Read> reads(NfcoreHic210Request.Request r){var result=new ArrayList<Read>();int index=0;for(var s:r.samples()){int library=0;for(var pair:s.libraries()){String prefix=String.format(Locale.ROOT,"data/reads/%06d/",++index);result.add(new Read(s.id(),++library,pair.first(),pair.second(),prefix+"first/"+basename(pair.first()),prefix+"second/"+basename(pair.second())));}}return result;}
    static String samplesheet(NfcoreHic210Request.Request r,NfcoreInputBindings.Layout layout){var text=new StringBuilder("sample,fastq_1,fastq_2\n");for(var read:reads(r))text.append(read.sample()).append(',').append(layout.captured(read.firstRelative())).append(',').append(layout.captured(read.secondRelative())).append('\n');return text.toString();}
    static List<String> outputs(NfcoreHic210Request.Request r){var result=new ArrayList<>(List.of("pipeline_info","samplesheet","fastqc","hicpro","contact_maps","compartments","distance_decay","multiqc"));String caller=r.science().get("tads_caller").toString();if(caller.contains("insulation"))result.add("tads/insulation");if(caller.contains("hicexplorer"))result.add("tads/hicExplorer");return result;}
    private static Map<String,Object> input(String name){return Map.of("$input","bundle","path",name);}
    static Map<String,Object> recipe(String producer,NfcoreHic210Request.Request r)throws IOException{
        NfcoreHic210Request.path(producer);String materialized=producer+"/materialized";var params=new LinkedHashMap<String,Object>(r.science());if(params.get("res_zoomify").equals(""))params.put("res_zoomify",null);params.put("input",input("samplesheet.csv"));params.put("fasta",input("data/reference/"+basename(r.fasta())));params.put("custom_config_base",input("config"));params.put("igenomes_ignore",true);params.put("outdir",Map.of("$output",""));params.put("max_cpus",r.taskCpus());params.put("max_memory",r.taskMemory()+" B");params.put("max_time",r.taskSeconds()+" s");
        // All source-default analyses stay selected. A request cannot disable a failed branch.
        for(String key:List.of("skip_maps","skip_balancing","skip_mcool","skip_dist_decay","skip_compartments","skip_tads","skip_multiqc","dnase","split_fastq"))params.put(key,false);
        var result=new LinkedHashMap<String,Object>();result.put("schema_version",1);result.put("engine_profile",NfcoreHic210Profile.ENGINE);result.put("workflow",Map.of("path",materialized+"/upstream","entrypoint","main.nf","configs",List.of("nextflow.config","runtime/host.config"),"profiles",List.of("singularity")));result.put("resources",Map.of("bundle",Map.of("path",materialized)));result.put("parameters",params);result.put("required_tools",List.of(Map.of("name","singularity","path",r.containerHome()+"/bin/apptainer")));result.put("outputs",outputs(r).stream().map(name->Map.of("path",name,"kind","directory","allow_empty",false)).toList());result.put("require_tasks",true);result.put("limits",r.limits());return result;
    }
    static NextflowRecipe.Request prepare(Path root,NfcoreHic210Request.Request r,Path admission)throws IOException{
        var materialized=Files.createDirectory(root.resolve("materialized"));var layout=NfcoreInputBindings.plan(root+"/engine",root+"/materialized");Path declaredImages=Path.of(r.imageSet());if(!Files.exists(declaredImages))throw new NextflowProcess.Unavailable("Required complete original image declaration is missing; restore it or retain the skipped analysis");Pin declarationBefore=pin(declaredImages,1048576,()->{});Files.copy(declaredImages,root.resolve("supplied-image-set.json"));if(!declarationBefore.equals(pin(root.resolve("supplied-image-set.json"),1048576,()->{}))||!declarationBefore.equals(pin(declaredImages,1048576,()->{})))throw new IOException("Original image declaration changed during capture");writeJson(root.resolve("engine-recipe.json"),recipe(root.toString(),r));var bound=NextflowRecipe.read(root.resolve("engine-recipe.json"));
        var runtime=new NfcoreContainerSet(Path.of(r.containerHome()),root.resolve("supplied-image-set.json"),admission,bound.process(),NfcoreHic210Profile.RESOURCE+"IMAGES.json",NfcoreHic210Profile.IMAGES);runtime.health();NfcoreHic210Profile.copySource(Path.of(r.source()),materialized.resolve("upstream"));var declaration=object(object(json(root.resolve("supplied-image-set.json"),1048576)).get("images"));var ownedImages=new TreeMap<String,String>();var copies=new ArrayList<Map<String,Object>>();long[] total={0};
        for(var entry:new TreeMap<>(NfcoreHic210Profile.images()).entrySet()){
            String uri=text(entry.getKey());Pin expected=fingerprint(object(entry.getValue()).get("pin"),5000000000L);String member="images/"+expected.sha256()+".sif";copy(Path.of(text(declaration.get(uri))),materialized.resolve(member),member,bound,copies,total);if(!pin(materialized.resolve(member),5000000000L,()->{}).equals(expected))throw new IOException("Complete original Hi-C image differs: "+uri);ownedImages.put(uri,materialized.resolve(member).toString());
        }
        copy(Path.of(r.fasta()),materialized.resolve("data/reference/"+basename(r.fasta())),"data/reference/"+basename(r.fasta()),bound,copies,total);var mapping=new ArrayList<Map<String,Object>>();
        for(var read:reads(r)){copy(Path.of(read.first()),materialized.resolve(read.firstRelative()),read.firstRelative(),bound,copies,total);copy(Path.of(read.second()),materialized.resolve(read.secondRelative()),read.secondRelative(),bound,copies,total);mapping.add(Map.of("sample",read.sample(),"technical_library",read.library(),"original_fastq_1",read.first(),"original_fastq_2",read.second(),"captured_fastq_1",layout.captured(read.firstRelative()),"captured_fastq_2",layout.captured(read.secondRelative())));}
        Files.writeString(materialized.resolve("samplesheet.csv"),samplesheet(r,layout),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.createDirectory(materialized.resolve("config"));Files.writeString(materialized.resolve("config/nfcore_custom.config"),EXTERNAL,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.createDirectory(materialized.resolve("upstream/runtime"));Files.writeString(materialized.resolve("upstream/runtime/host.config"),NfcoreHic210Profile.overlay(root+"/engine",layout.capturedRoot(),r.executorCpus(),r.executorMemory()),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);writeJson(root.resolve("image-set.json"),Map.of("schema_version",1,"images",ownedImages));writeJson(root.resolve("materialized-index.json"),NfcoreRnasplice104Prepare.materializedIndex(materialized,bound.capture().fileBytes()));
        writeJson(root.resolve("prepared.json"),Map.of("schema_version",1,"producer_root",root.toString(),"source_profile",NfcoreHic210Profile.SOURCE,"image_profile",NfcoreHic210Profile.IMAGES,"reference_assembly_label",r.assemblyLabel(),"reference_assembly_independently_certified",false,"input_mapping",mapping,"copied_inputs",copies,"scientific_identifiers_repaired",false));runtime.verify();return bound;
    }
    private static void copy(Path source,Path target,String member,NextflowRecipe.Request bounds,List<Map<String,Object>> records,long[] total)throws IOException{
        if(!Files.exists(source))throw new NextflowProcess.Unavailable("Required complete original Hi-C input/image is missing: "+source+". Restore the permitted exact file or retain the skipped analysis");Pin before=pin(source,bounds.capture().fileBytes(),()->{});total[0]=Math.addExact(total[0],before.bytes());if(total[0]>bounds.capture().bytes())throw new IOException("Whole Hi-C materialization exceeds capacity; no input reduction");Files.createDirectories(target.getParent());Files.copy(source,target);if(!pin(target,bounds.capture().fileBytes(),()->{}).equals(before)||!pin(source,bounds.capture().fileBytes(),()->{}).equals(before))throw new IOException("Original Hi-C input changed during capture: "+source);records.add(Map.of("original_path",source.toString(),"materialized_member",member,"pin",before));
    }
}
